import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    system = platform.system().lower()
    data = []
    start_time = time.time()
    while True:
        current_time = time.time()
        timestamp = current_time
        try:
            if "windows" in system:
                cmd = ["wmic", "cpu", "get", "loadpercentage"]
                result = subprocess.check_output(cmd, universal_newlines=True)
                lines = [line.strip() for line in result.splitlines() if line.strip()]
                if len(lines) >= 2:
                    try:
                        cpu_usage = float(lines[1])
                    except ValueError:
                        cpu_usage = None
                else:
                    cpu_usage = None
            else:
                cmd = ["sh", "-c", "top -bn1 | grep 'Cpu' || top -bn1 | grep 'Cpu(s)'"]
                result = subprocess.check_output(cmd, universal_newlines=True)
                line = result.strip()
                cpu_usage = None
                for token in line.replace(",", "").split():
                    if "%" in token or "id" in token:
                        continue
                if "id" in line:
                    parts = line.replace(",", "").split()
                    idle_val = None
                    for i, tok in enumerate(parts):
                        if tok.startswith("id") or tok == "id":
                            if i > 0:
                                try:
                                    idle_val = float(parts[i - 1])
                                except ValueError:
                                    idle_val = None
                            break
                    if idle_val is not None:
                        cpu_usage = 100.0 - idle_val
                if cpu_usage is None:
                    cmd2 = ["sh", "-c", "mpstat 1 1 | awk '/Average/ && $12 ~ /[0-9.]+/ {print 100-$12}'"]
                    try:
                        result2 = subprocess.check_output(cmd2, universal_newlines=True)
                        cpu_usage = float(result2.strip())
                    except Exception:
                        cpu_usage = None
        except Exception:
            cpu_usage = None
        data.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        if current_time - start_time + interval > duration:
            break
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(data, f)
        return LOGFILE_PATH
    except IOError:
        return None

