import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    records = []
    system = platform.system().lower()
    if "windows" in system:
        cmd = ["wmic", "cpu", "get", "loadpercentage"]
        def get_cpu():
            try:
                output = subprocess.check_output(cmd).decode().strip().splitlines()
                values = [line.strip() for line in output if line.strip() and "loadpercentage" not in line.lower()]
                if not values:
                    return None
                return float(values[0])
            except Exception:
                return None
    else:
        cmd = ["sh", "-c", "top -bn1 | grep 'Cpu' || top -bn1 | grep 'Cpu(s)'"]
        def get_cpu():
            try:
                output = subprocess.check_output(cmd).decode()
                line = output.strip()
                for part in line.replace(',', ' ').split():
                    if part.endswith("id") or part.endswith("id,"):
                        try:
                            idle = float(part.split("%")[0])
                            return 100.0 - idle
                        except Exception:
                            continue
                for part in line.replace(',', ' ').split():
                    if part.endswith("us") or part.endswith("us,"):
                        try:
                            return float(part.split("%")[0])
                        except Exception:
                            continue
                return None
            except Exception:
                return None
    start_time = time.time()
    while True:
        now = time.time()
        if now - start_time > duration:
            break
        cpu_usage = get_cpu()
        record = {"timestamp": now, "cpu_usage": cpu_usage}
        records.append(record)
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(records, f)
        return LOGFILE_PATH
    except IOError:
        return None

