LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    system = platform.system().lower()
    data = []
    start_time = time.time()
    while True:
        timestamp = time.time()
        if system == "windows":
            try:
                result = subprocess.check_output(["wmic", "cpu", "get", "loadpercentage"], stderr=subprocess.STDOUT)
                lines = result.decode().strip().splitlines()
                value = None
                for line in lines:
                    line = line.strip()
                    if not line or "loadpercentage" in line.lower():
                        continue
                    try:
                        value = float(line)
                        break
                    except ValueError:
                        continue
                cpu_usage = value if value is not None else 0.0
            except Exception:
                cpu_usage = 0.0
        else:
            try:
                result = subprocess.check_output(["sh", "-c", "top -bn1 | grep 'Cpu' || top -bn1 | grep 'CPU'"], stderr=subprocess.STDOUT)
                text = result.decode()
                percent = None
                num = ""
                for ch in text:
                    if ch.isdigit() or ch == ".":
                        num += ch
                    elif num:
                        try:
                            percent = float(num)
                            break
                        except ValueError:
                            num = ""
                    else:
                        continue
                if percent is None and num:
                    try:
                        percent = float(num)
                    except ValueError:
                        percent = 0.0
                cpu_usage = percent if percent is not None else 0.0
            except Exception:
                cpu_usage = 0.0
        data.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        elapsed = time.time() - start_time
        if elapsed >= duration:
            break
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(data, f)
        return LOGFILE_PATH
    except IOError:
        return None

