        cpu_usage = None
        try:
            if "windows" in system:
                cmd = ["wmic", "cpu", "get", "loadpercentage", "/value"]
                proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                out, err = proc.communicate()
                if out:
                    text = out.decode(errors="ignore")
                    for line in text.splitlines():
                        line = line.strip()
                        if line.lower().startswith("loadpercentage="):
                            try:
                                cpu_usage = float(line.split("=", 1)[1].strip())
                            except ValueError:
                                cpu_usage = None
                            break
            else:
                cmd = ["sh", "-c", "top -bn1 | grep '%Cpu' || top -bn1 | grep 'Cpu(s)'"]
                proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                out, err = proc.communicate()
                if out:
                    text = out.decode(errors="ignore")
                    line = text.strip().splitlines()[0] if text.strip() else ""
                    parts = line.replace(",", " ").split()
                    idle = None
                    for i, p in enumerate(parts):
                        if p.lower().startswith("id") or p.lower().startswith("id,"):
                            try:
                                idle = float(parts[i - 1])
                            except Exception:
                                idle = None
                            break
                    if idle is not None:
                        cpu_usage = 100.0 - idle
            if cpu_usage is not None:
                records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        except Exception:
            pass
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH

