import subprocess
import os
import json
from datetime import datetime
def task_func(script_name='backup.sh', log_file='/home/user/backup_log.json'):
    script_path = os.path.abspath(script_name)
    if not os.path.exists(script_path):
        raise FileNotFoundError("Script file does not exist")
    start_time = datetime.now()
    start_str = start_time.strftime('%Y-%m-%d %H:%M:%S')
    try:
        result = subprocess.run(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        exit_status = result.returncode
    except Exception as e:
        raise RuntimeError(f"Error executing script: {e}")
    end_time = datetime.now()
    end_str = end_time.strftime('%Y-%m-%d %H:%M:%S')
    log_data = {
        'start_time': start_str,
        'end_time': end_str,
        'exit_status': exit_status
    }
    try:
        if os.path.exists(log_file):
            try:
                with open(log_file, 'r') as f:
                    existing = json.load(f)
            except Exception:
                existing = []
        else:
            existing = []
        if isinstance(existing, list):
            existing.append(log_data)
            to_write = existing
        else:
            to_write = [existing, log_data]
        with open(log_file, 'w') as f:
            json.dump(to_write, f)
    except Exception:
        pass
    return log_data

import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    if not isinstance(r_script_path, str) or not isinstance(output_path, str):
        raise TypeError("r_script_path and output_path must be strings")
    if not isinstance(duration, int):
        raise TypeError("duration must be an integer")
    if r_script_path == "" or not os.path.exists(r_script_path):
        raise OSError("Invalid R script path")
    output_path = os.path.normpath(output_path)
    try:
        subprocess.Popen(["Rscript", r_script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except FileNotFoundError:
        return False, "File not generated within the specified duration."
    end_time = time.time() + duration
    pattern_exists = "*" in output_path or "?" in output_path or "[" in output_path
    while time.time() <= end_time:
        if pattern_exists:
            matches = glob.glob(output_path)
            if matches:
                return True, "File generated successfully within the specified duration."
        else:
            if os.path.exists(output_path):
                return True, "File generated successfully within the specified duration."
        time.sleep(1)
    return False, "File not generated within the specified duration."

