        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            continue
    gone, alive = psutil.wait_procs([psutil.Process(pid) for pid in running_pids if psutil.pid_exists(pid)], timeout=3)
