import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    failed_files = []
    if not os.path.isdir(src_folder):
        return {
            'success': False,
            'message': 'Source folder does not exist',
            'failed_files': []
        }
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder)
        except Exception:
            return {
                'success': False,
                'message': 'Failed to create destination folder',
                'failed_files': []
            }
    files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]
    if not files:
        return {
            'success': True,
            'message': 'No files to compress',
            'failed_files': []
        }
    processes = {}
    for file_path in files:
        try:
            p = subprocess.Popen(['gzip', '-k', file_path], stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
            processes[file_path] = p
        except Exception:
            failed_files.append(os.path.basename(file_path))
    for file_path, process in processes.items():
        stdout, stderr = process.communicate()
        if process.returncode != 0:
            failed_files.append(os.path.basename(file_path))
            continue
        gz_path = file_path + '.gz'
        if not os.path.exists(gz_path):
            failed_files.append(os.path.basename(file_path))
            continue
        try:
            shutil.move(gz_path, os.path.join(dst_folder, os.path.basename(gz_path)))
        except Exception:
            failed_files.append(os.path.basename(file_path))
    success = len(failed_files) == 0
    if success:
        message = 'All files compressed and moved successfully'
    else:
        message = 'Some files failed to compress or move'
    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

