import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not os.path.exists(script_path):
        raise OSError("Script path does not exist")
    start_time = time.time()
    proc = subprocess.Popen(['bash', script_path])
    p = psutil.Process(proc.pid)
    cpu_usage = 0.0
    mem_usage = 0
    last_time = time.time()
    try:
        while True:
            if time.time() - start_time > timeout:
                proc.terminate()
                try:
                    proc.wait(timeout=1)
                except Exception:
                    proc.kill()
                break
            try:
                if not p.is_running() or p.status() == psutil.STATUS_ZOMBIE:
                    break
            except psutil.NoSuchProcess:
                break
            time.sleep(0.1)
            now = time.time()
            interval = now - last_time
            last_time = now
            try:
                cpu_percent = p.cpu_percent(interval=None)
                mem_info = p.memory_info()
            except psutil.NoSuchProcess:
                break
            cpu_usage += cpu_percent * interval
            mem_usage += mem_info.rss
            if proc.poll() is not None:
                try:
                    if not p.is_running() or p.status() == psutil.STATUS_ZOMBIE:
                        break
                except psutil.NoSuchProcess:
                    break
        try:
            if p.is_running() and p.status() != psutil.STATUS_ZOMBIE:
                proc.wait(timeout=1)
        except (psutil.NoSuchProcess, psutil.ZombieProcess, psutil.AccessDenied, subprocess.TimeoutExpired):
            pass
    finally:
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=1)
            except Exception:
                proc.kill()
    return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}

