import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    failed_files = []
    if not os.path.isdir(src_folder):
        return {'success': False, 'message': 'Source folder does not exist', 'failed_files': []}
    if not os.path.isdir(dst_folder):
        try:
            os.makedirs(dst_folder, exist_ok=True)
        except Exception:
            return {'success': False, 'message': 'Failed to create destination folder', 'failed_files': []}
    files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]
    if not files:
        return {'success': True, 'message': 'No files to compress', 'failed_files': []}
    processes = []
    file_map = {}
    for f in files:
        try:
            p = subprocess.Popen(['gzip', '-k', f])
            processes.append(p)
            file_map[p.pid] = f
        except Exception:
            failed_files.append(os.path.basename(f))
    for p in processes:
        ret = p.wait()
        orig_file = file_map.get(p.pid)
        if ret != 0:
            if orig_file is not None:
                failed_files.append(os.path.basename(orig_file))
            continue
        gz_file = orig_file + '.gz' if orig_file is not None else None
        if gz_file is None or not os.path.exists(gz_file):
            if orig_file is not None:
                failed_files.append(os.path.basename(orig_file))
            continue
        try:
            shutil.move(gz_file, os.path.join(dst_folder, os.path.basename(gz_file)))
        except Exception:
            failed_files.append(os.path.basename(orig_file))
    success = len(failed_files) == 0
    if success:
        message = 'All files compressed and moved successfully'
    else:
        message = 'Some files failed to compress or move'
    return {'success': success, 'message': message, 'failed_files': failed_files}

